# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


def make(last, first, section, email):
    return Student("1", last, first, section, email)


class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            make("Young", "Al", "B", "al@x.org"),
            make("Abel", "Bobby", "A", "bob@x.org")
        ])
        self.assertEqual(rows, [
            "Abel, Bobby  A  bob@x.org",
            "Young, Al    B  al@x.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([make("Abel", "Bobby", "A", None)])
        self.assertIn("Abel, Bobby", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
